mapper.select:
select e.*, e.phone as phone, e.email as email, e.address as address, e.detailed_address as detailedAddress, e.post_code as postCode, COALESCE(e.hire_date, DATE(e.created_at)) as hireDate, e.employee_status_code as status, p.position_name as positionName, d.department_name as departmentName from employee e left join positions p on p.position_id = e.position_id left join department d on e.department_id = d.department_id where 1=1
AND ( e.name = #{request.keyword} OR e.employee_no = #{request.keyword} )
AND d.department_name = #{request.departmentName}
AND p.position_name = #{request.positionName}
AND e.employee_status_code = #{request.employeeStatusCode}
limit #{size} offset #{offset}
